configuration.tbelScript:
// Access telemetry values
var remoteSwitching = msg.values ? msg.values.remoteSwitching : null;
var buttonNo = msg.values ? msg.values.buttonNo : null;
var targetDeviceId = metadata.targetDeviceId;

if (remoteSwitching && buttonNo && targetDeviceId) {
    // Build exact RPC payload
    var rpcPayload = {
        method: 'remoteSwitch',
        params: {
            remoteSwitching: remoteSwitching,
            buttonNo: buttonNo
        }
    };

    // Update message
    msg = rpcPayload;
    msgType = 'RPC_REQUEST';
} else {
    // No target/fields - log and skip RPC (continue as original)
    if (!targetDeviceId) {
        log('No target device via Controls relation');
    }
    if (!remoteSwitching || !buttonNo) {
        log('Missing remoteSwitching or buttonNo');
    }
}

return {msg: msg, metadata: metadata, msgType: msgType};

